import React, { useState } from "react";
import { Pressable, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { TemplateShell, SectionHeading } from "./template-shell";
import { useSkeuo } from "../theme";
import { SkeuoCard } from "../skeuo-card";
import { SkeuoButton } from "../skeuo-button";
import { SkeuoInput } from "../skeuo-input";
import { SkeuoDialog } from "../skeuo-dialog";
import { SkeuoSwitch } from "../skeuo-switch";
import { SummaryCard } from "../blocks/summary-card";
import {
  TransactionList,
  sampleTransactions,
} from "../blocks/transaction-list";
import { ActivityChart } from "../blocks/activity-chart";
const items = [
  { value: "home", label: "Home" },
  { value: "transactions", label: "Transactions" },
  { value: "analysis", label: "Analysis" },
  { value: "profile", label: "Profile" },
];
export function PocketTemplate() {
  const { colors: c } = useSkeuo();
  const [tab, setTab] = useState("home");
  const [search, setSearch] = useState("");
  const [adding, setAdding] = useState(false);
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");
  const [transactions, setTransactions] = useState(sampleTransactions);
  const [privateBalance, setPrivateBalance] = useState(false);
  const [income, setIncome] = useState(false);
  const [name, setName] = useState("Alex Morgan");
  const [cash, setCash] = useState(4260);
  return (
    <TemplateShell
      name="pocket"
      items={items}
      value={tab}
      onValueChange={setTab}
    >
      {tab === "home" ? (
        <>
          <SectionHeading title={`Good morning, ${name.trim().split(/\s+/)[0] || "there"}.`} />
          <LinearGradient
            colors={["#31584b", "#182f28"]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={{
              borderRadius: 18,
              borderWidth: 1,
              borderColor: "#577365",
              padding: 18,
              gap: 15,
            }}
          >
            <View style={{ gap: 6 }}>
              <Text style={{ color: "#d6e3d9", fontSize: 13 }}>Total balance</Text>
              <Text
                adjustsFontSizeToFit
                numberOfLines={1}
                style={{
                  color: "#fcf9ef",
                  fontSize: 44,
                  fontWeight: "500",
                  letterSpacing: -2,
                  fontVariant: ["tabular-nums"],
                }}
              >
                {privateBalance ? "••••••" : `₹${(38600 + cash).toLocaleString("en-IN")}`}
              </Text>
            </View>
            <View
              style={{
                flexDirection: "row",
                gap: 8,
                borderTopWidth: 1,
                borderColor: "#648073",
                paddingTop: 12,
              }}
            >
              {[
                ["Bank", "₹32,400"],
                ["Cash", `₹${cash.toLocaleString("en-IN")}`],
                ["Shared", "₹6,200"],
              ].map(([label, value]) => (
                <View key={label} style={{ flex: 1, gap: 4 }}>
                  <Text style={{ color: "#d6e3d9", fontSize: 11 }}>{label}</Text>
                  <Text
                    adjustsFontSizeToFit
                    numberOfLines={1}
                    style={{ color: "#fcf9ef", fontSize: 15, fontWeight: "600" }}
                  >
                    {privateBalance ? "••••" : value}
                  </Text>
                </View>
              ))}
            </View>
          </LinearGradient>
          <SkeuoButton variant="accent" onPress={() => setAdding(true)}>
            + Add a transaction
          </SkeuoButton>
          <View>
            <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
              <Text style={{ color: c.ink, fontWeight: "600", fontSize: 16 }}>
                Recent activity
              </Text>
              <Pressable accessibilityRole="button" hitSlop={10} onPress={() => setTab("transactions")}>
                <Text style={{ color: c.accent, fontWeight: "600", fontSize: 13 }}>View all</Text>
              </Pressable>
            </View>
            <TransactionList items={transactions.slice(0, 2)} />
          </View>
        </>
      ) : tab === "transactions" ? (
        <>
          <SectionHeading
            title="Transactions"
          />
          <SkeuoInput
            label="Search transactions"
            placeholder="Coffee, groceries…"
            value={search}
            onChangeText={setSearch}
          />
          <SkeuoButton onPress={() => setAdding(true)}>
            + Add transaction
          </SkeuoButton>
          <TransactionList
            items={transactions.filter((item) =>
              item.name.toLowerCase().includes(search.toLowerCase()),
            )}
          />
        </>
      ) : tab === "analysis" ? (
        <>
          <SectionHeading
            title="Spending overview"
            detail="Sample month"
          />
          <SummaryCard
            label="Spent this month"
            value="₹12,840"
            detail="₹2,160 under your monthly plan"
          />
          <SkeuoCard>
            <Text style={{ color: c.ink, fontWeight: "600" }}>
              Daily spending
            </Text>
            <ActivityChart label="Illustrative daily spending" />
            {[
              ["Food & drink", "42%"],
              ["Shopping", "31%"],
              ["Transport", "27%"],
            ].map(([label, value]) => (
              <View
                key={label}
                style={{
                  flexDirection: "row",
                  justifyContent: "space-between",
                }}
              >
                <Text style={{ color: c.muted }}>{label}</Text>
                <Text style={{ color: c.ink }}>{value}</Text>
              </View>
            ))}
          </SkeuoCard>
        </>
      ) : (
        <>
          <SectionHeading
            title="Profile"
          />
          <SkeuoCard>
            <SkeuoInput
              label="Display name"
              value={name}
              onChangeText={setName}
            />
            <SkeuoSwitch
              label="Hide balances"
              checked={privateBalance}
              onCheckedChange={setPrivateBalance}
            />
            <Text style={{ color: c.muted, fontSize: 12, lineHeight: 19 }}>
              Fictional sample data. Changes stay in this session. No bank
              connection or account required.
            </Text>
          </SkeuoCard>
        </>
      )}
      <SkeuoDialog
        open={adding}
        onOpenChange={setAdding}
        title="A new transaction"
      >
        <SkeuoInput
          label="Description"
          value={description}
          onChangeText={setDescription}
        />
        <SkeuoInput
          label="Amount in rupees"
          value={amount}
          onChangeText={setAmount}
          keyboardType="decimal-pad"
        />
        <SkeuoSwitch
          label="This is income"
          checked={income}
          onCheckedChange={setIncome}
        />
        <SkeuoButton
          variant="accent"
          disabled={
            !description.trim() ||
            !Number.isFinite(Number(amount)) ||
            Number(amount) <= 0
          }
          onPress={() => {
            setCash(previous => previous + (income ? 1 : -1) * Number(amount));
            setTransactions((previous) => [
              {
                id: String(Date.now()),
                name: description.trim(),
                category: "Cash · Added just now",
                amount: `${income ? "+" : "−"}₹${Number(amount).toLocaleString("en-IN")}`,
                income,
              },
              ...previous,
            ]);
            setDescription("");
            setAmount("");
            setAdding(false);
            setTab("transactions");
          }}
        >
          Add transaction
        </SkeuoButton>
      </SkeuoDialog>
    </TemplateShell>
  );
}

import React from "react";
import { ScrollView, Text, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useSkeuo } from "../theme";
import {
  SkeuoBottomBar,
  type BottomBarItem,
  type BottomBarVariant,
} from "../skeuo-bottom-bar";
export function TemplateShell({
  name,
  subtitle,
  children,
  items,
  value,
  onValueChange,
  variant = "dock",
  action,
}: {
  name: string;
  subtitle?: string;
  children: React.ReactNode;
  items: BottomBarItem[];
  value: string;
  onValueChange: (value: string) => void;
  variant?: BottomBarVariant;
  action?: React.ReactNode;
}) {
  const { colors: c } = useSkeuo();
  const insets = useSafeAreaInsets();
  return (
    <View
      style={{ flex: 1, backgroundColor: c.background, paddingTop: insets.top }}
    >
      <View
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          alignItems: "center",
          paddingHorizontal: 22,
          paddingTop: subtitle ? 18 : 12,
          paddingBottom: subtitle ? 18 : 16,
        }}
      >
        <View style={{ gap: 3 }}>
          <Text
            style={{
              color: c.ink,
              fontSize: 20,
              fontWeight: "700",
              letterSpacing: -0.6,
            }}
          >
            {name}
            <Text style={{ color: c.accent }}>.</Text>
          </Text>
          {subtitle && (
            <Text style={{ color: c.muted, fontSize: 10 }}>{subtitle}</Text>
          )}
        </View>
        {action ?? (
          <View
            style={{
              height: 34,
              width: 34,
              borderRadius: 17,
              backgroundColor: c.well,
              borderWidth: 1,
              borderColor: c.edge,
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <Text style={{ color: c.muted, fontSize: 11 }}>AM</Text>
          </View>
        )}
      </View>
      <ScrollView
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={{
          paddingHorizontal: 22,
          paddingBottom: 24,
          gap: subtitle ? 24 : 18,
        }}
      >
        {children}
      </ScrollView>
      <SkeuoBottomBar
        items={items}
        value={value}
        onValueChange={onValueChange}
        variant={variant}
        bottomInset={insets.bottom}
      />
    </View>
  );
}
export function SectionHeading({
  title,
  detail,
}: {
  title: string;
  detail?: string;
}) {
  const { colors: c } = useSkeuo();
  return (
    <View style={{ gap: 7 }}>
      <Text
        accessibilityRole="header"
        style={{
          fontSize: 29,
          fontWeight: "500",
          color: c.ink,
          letterSpacing: -1,
        }}
      >
        {title}
      </Text>
      {detail && (
        <Text style={{ color: c.muted, fontSize: 13, lineHeight: 20 }}>
          {detail}
        </Text>
      )}
    </View>
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}

import React from "react";
import { Pressable, Text, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { useFeedback, useSkeuo } from "./theme";
import { SkeuoGlyph } from "./icons";
import { SkeuoDockBar, type DockBarProps } from "./skeuo-dock-bar";

export type { BottomBarItem } from "./skeuo-dock-bar";
export type BottomBarVariant = "dock" | "keys" | "rail" | "pill";
export function SkeuoBottomBar({
  items,
  value,
  onValueChange,
  variant = "dock",
  bottomInset = 0,
}: DockBarProps & { variant?: BottomBarVariant }) {
  if (variant === "dock") {
    return <SkeuoDockBar {...{ items, value, onValueChange, bottomInset }} />;
  }
  return <LabeledBottomBar {...{ items, value, onValueChange, variant, bottomInset }} />;
}

function LabeledBottomBar({
  items,
  value,
  onValueChange,
  variant,
  bottomInset = 0,
}: DockBarProps & { variant: Exclude<BottomBarVariant, "dock"> }) {
  const { colors: c } = useSkeuo();
  const feedback = useFeedback();
  return (
    <View
      accessibilityRole="tablist"
      accessibilityLabel="Bottom navigation"
      style={{
        paddingBottom: Math.max(8, bottomInset),
        paddingTop: 12,
        paddingHorizontal: variant === "rail" ? 0 : 12,
        backgroundColor: c.background,
      }}
    >
      <View
        style={{
          flexDirection: "row",
          gap: variant === "keys" ? 8 : 2,
          padding: variant === "pill" ? 5 : 0,
          borderWidth: variant === "pill" ? 1 : 0,
          borderColor: c.edge,
          borderRadius: variant === "pill" ? 32 : 16,
          backgroundColor: variant === "keys" ? c.background : c.well,
        }}
      >
        {items.map((item) => {
          const active = item.value === value;
          return (
            <Pressable
              key={item.value}
              accessibilityRole="tab"
              aria-selected={active}
              aria-disabled={!!item.disabled}
              accessibilityLabel={item.label}
              accessibilityState={{
                selected: active,
                disabled: !!item.disabled,
              }}
              disabled={item.disabled}
              onPress={() => {
                feedback();
                onValueChange(item.value);
              }}
              style={({ pressed }) => ({
                flex: 1,
                minHeight: 60,
                borderRadius: variant === "pill" ? 26 : 10,
                borderWidth: variant === "keys" ? 1 : 0,
                borderBottomWidth:
                  variant === "keys"
                    ? pressed
                      ? 1
                      : 4
                    : active && variant === "rail"
                      ? 3
                      : 1,
                borderColor: active && variant === "rail" ? c.accent : c.edge,
                backgroundColor: active
                  ? c.raised
                  : variant === "keys"
                    ? c.surface
                    : "transparent",
                opacity: item.disabled ? 0.4 : 1,
                transform: [{ translateY: pressed ? 2 : 0 }],
                overflow: "hidden",
              })}
            >
              <LinearGradient
                colors={active ? [c.raised, c.surface] : [c.well, c.well]}
                style={{
                  flex: 1,
                  alignItems: "center",
                  justifyContent: "center",
                  paddingVertical: 8,
                  gap: 3,
                }}
              >
                {item.icon ?? (
                  <SkeuoGlyph
                    name={item.value}
                    color={active ? c.accent : c.muted}
                  />
                )}
                <Text
                  numberOfLines={1}
                  style={{
                    fontSize: 10,
                    fontWeight: active ? "700" : "500",
                    color: active ? c.ink : c.muted,
                  }}
                >
                  {item.label}
                </Text>
              </LinearGradient>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

import { Text } from "react-native";
/** Simple line symbols keep the portable controls independent of an icon package. Hosts may pass their own icons. */
export function SkeuoGlyph({
  name,
  color = "#686863",
  size = 21,
}: {
  name: string;
  color?: string;
  size?: number;
}) {
  const symbols: Record<string, string> = {
    home: "⌂",
    transactions: "⇄",
    analysis: "▥",
    profile: "○",
    focus: "◷",
    habits: "✓",
    journal: "≡",
    settings: "⚙",
    activity: "↗",
    goals: "◎",
    saved: "▱",
    add: "+",
    arrow: "↗",
    back: "‹",
    next: "›",
    play: "▶",
    pause: "Ⅱ",
    sound: "♪",
  };
  return (
    <Text
      accessible={false}
      style={{
        color,
        fontSize: size,
        lineHeight: size + 4,
        textAlign: "center",
      }}
    >
      {symbols[name] ?? "◇"}
    </Text>
  );
}

import type { ReactNode } from "react";
import { Pressable, ScrollView, StyleSheet, View } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import Svg, { Path } from "react-native-svg";
import { SkeuoGlyph } from "./icons";
import { themes, useFeedback, useSkeuo } from "./theme";

export type BottomBarItem = {
  value: string;
  label: string;
  icon?: ReactNode;
  disabled?: boolean;
};

export type DockBarProps = {
  items: BottomBarItem[];
  value: string;
  onValueChange: (value: string) => void;
  bottomInset?: number;
};

const iconPaths: Record<string, string> = {
  home: "m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z",
  transactions: "M4 8h16m-4-4 4 4-4 4M20 16H4m4-4-4 4 4 4",
  analysis: "M4 4v16h16M9 16v-4m5 4V8m5 8V5",
  profile: "M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21a8 8 0 0 1 16 0",
};

export function SkeuoDockBar({
  items,
  value,
  onValueChange,
  bottomInset = 0,
}: DockBarProps) {
  const { colors, dark } = useSkeuo();
  const feedback = useFeedback();
  // Use the Section Dock materials with the website’s green accent.
  const edge = dark ? "#484946" : "#c6c7c1";
  const highlight = dark ? "#ffffff1e" : "#fff";
  const shadow = dark ? "#00000099" : "#00000017";
  const keyFace = dark ? "#292a29" : "#f9f9f7";
  const defaults = dark ? themes.dark : themes.light;
  const muted = dark && colors.muted === defaults.muted ? "#92928d" : colors.muted;
  const accent = colors.accent === defaults.accent
    ? dark
      ? { top: "#bbcec2", edge: "#6f8a79", base: "#4d6558" }
      : { top: "#487b68", edge: "#294b3e", base: "#213c32" }
    : { top: colors.accent, edge: colors.accent, base: colors.accent };
  const accentHighlight = dark ? "#ffffff80" : "#ffffff60";
  const accentRecess = dark ? "#00000026" : "#00000040";

  return (
    <View style={{ paddingBottom: Math.max(0, bottomInset), backgroundColor: colors.background }}>
      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        keyboardShouldPersistTaps="handled"
        style={styles.scroll}
        contentContainerStyle={styles.scrollContent}
      >
        <View
          accessibilityRole="tablist"
          accessibilityLabel="Bottom navigation"
          style={[
            styles.shell,
            {
              borderColor: edge,
              backgroundColor: colors.surface,
              boxShadow: `0 5px ${colors.base}, 0 6px ${edge}, 0 12px 20px ${shadow}`,
            },
          ]}
        >
          <LinearGradient
            pointerEvents="none"
            colors={[colors.raised, colors.surface]}
            start={gradientStart}
            end={gradientEnd}
            style={styles.shellFace}
          />
          <View
            pointerEvents="none"
            style={[
              styles.shellFace,
              { boxShadow: `inset 0 2px 1px ${highlight}, inset 1px 0 ${highlight}, inset 0 -2px ${colors.base}` },
            ]}
          />
          <View
            style={[
              styles.track,
              {
                borderColor: colors.edge,
                backgroundColor: colors.base,
                boxShadow: `inset 0 5px 9px ${shadow}, inset 2px 0 5px ${shadow}, inset -1px 0 3px ${shadow}, 0 1px ${highlight}`,
              },
            ]}
          >
            {items.map((item) => {
              const active = item.value === value;
              const keyEdge = active ? accent.edge : edge;
              const keyBase = active ? accent.base : colors.base;
              const keyTop = active ? accent.top : keyFace;
              const keyBottom = active ? colors.accent : colors.surface;
              const ink = active ? colors.accentInk : muted;
              const path = Object.hasOwn(iconPaths, item.value) ? iconPaths[item.value] : undefined;

              return (
                <Pressable
                  key={item.value}
                  accessibilityRole="tab"
                  accessibilityLabel={item.label}
                  aria-selected={active}
                  aria-disabled={!!item.disabled}
                  accessibilityState={{ selected: active, disabled: !!item.disabled }}
                  disabled={item.disabled}
                  onPress={() => {
                    feedback();
                    onValueChange(item.value);
                  }}
                  style={({ pressed }) => [
                    styles.key,
                    {
                      borderColor: keyEdge,
                      backgroundColor: keyBottom,
                      boxShadow: pressed
                        ? `0 1px ${keyEdge}`
                        : `0 3px ${keyBase}, 0 4px ${keyEdge}, 0 6px 4px #00000025`,
                      opacity: item.disabled ? 0.4 : 1,
                      transform: [{ translateY: pressed ? 3 : 0 }],
                    },
                  ]}
                >
                  {({ pressed }) => (
                    <>
                      <LinearGradient
                        pointerEvents="none"
                        colors={[keyTop, keyBottom]}
                        start={gradientStart}
                        end={gradientEnd}
                        style={styles.keyFace}
                      />
                      <View
                        pointerEvents="none"
                        style={[
                          styles.keyFace,
                          {
                            boxShadow: pressed
                              ? `inset 0 2px 4px ${shadow}`
                              : `inset 0 2px ${active ? accentHighlight : highlight}, inset 2px 0 2px ${active ? "#ffffff25" : highlight}, inset 0 -3px ${keyBase}`,
                          },
                        ]}
                      />
                      <View
                        pointerEvents="none"
                        style={[
                          styles.keyInset,
                          {
                            borderColor: active ? accentHighlight : `${edge}73`,
                            boxShadow: `inset 0 2px 3px ${active ? accentRecess : shadow}, inset 0 -1px ${active ? accentHighlight : highlight}`,
                          },
                        ]}
                      />
                      <View pointerEvents="none" style={styles.icon}>
                        {item.icon ?? (path ? (
                          <Svg width={24} height={24} viewBox="0 0 24 24" accessible={false}>
                            <Path
                              d={path}
                              fill="none"
                              stroke={ink}
                              strokeWidth={1.6}
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            />
                          </Svg>
                        ) : <SkeuoGlyph name={item.value} color={ink} size={24} />)}
                      </View>
                    </>
                  )}
                </Pressable>
              );
            })}
          </View>
        </View>
      </ScrollView>
    </View>
  );
}

const gradientStart = { x: 0.15, y: 0 };
const gradientEnd = { x: 0.85, y: 1 };

const styles = StyleSheet.create({
  scroll: { flexGrow: 0 },
  scrollContent: {
    flexGrow: 1,
    justifyContent: "center",
    paddingHorizontal: 12,
    paddingTop: 4,
    paddingBottom: 16,
  },
  shell: { padding: 9, borderWidth: 1, borderRadius: 29 },
  shellFace: { ...StyleSheet.absoluteFillObject, borderRadius: 28 },
  track: {
    flexDirection: "row",
    gap: 12,
    paddingTop: 9,
    paddingHorizontal: 8,
    paddingBottom: 12,
    borderWidth: 1,
    borderRadius: 21,
  },
  key: {
    alignItems: "center",
    justifyContent: "center",
    width: 50,
    height: 50,
    borderWidth: 1,
    borderRadius: 12,
  },
  icon: { zIndex: 1 },
  keyFace: { ...StyleSheet.absoluteFillObject, borderRadius: 11 },
  keyInset: {
    position: "absolute",
    top: 4,
    left: 4,
    right: 4,
    bottom: 5,
    borderWidth: 1,
    borderRadius: 8,
